//! Monokl's core data types: code blocks, ranked results and diagnostics.
use std::ops::Range;

use camino::Utf8PathBuf;

/// The classification of a symbol.
///
/// Ordering is declaration order: ranking breaks ties by it, so reordering the variants reorders equal-score results.
///
/// Most variants apply to every language analyzer; `Impl` and `Macro` are Rust-specific, and `Other` is the catch-all.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
#[non_exhaustive]
pub enum SymbolKind {
    Function,
    Method,
    Constructor,
    Class,
    Struct,
    Enum,
    Interface,
    TypeAlias,
    Property,
    Field,
    Variable,
    Module,
    Impl,
    Macro,
    Other,
}

impl SymbolKind {
    /// The `camelCase` name agent output prints for this kind.
    #[must_use]
    pub fn as_str(self) -> &'static str {
        match self {
            Self::Function => "function",
            Self::Method => "method",
            Self::Constructor => "constructor",
            Self::Class => "class",
            Self::Struct => "struct",
            Self::Enum => "enum",
            Self::Interface => "interface",
            Self::TypeAlias => "typeAlias",
            Self::Property => "property",
            Self::Field => "field",
            Self::Variable => "variable",
            Self::Module => "module",
            Self::Impl => "impl",
            Self::Macro => "macro",
            Self::Other => "other",
        }
    }
}

/// A block of code matched by the search pipeline.
#[derive(Debug, Clone)]
pub struct CodeBlock {
    pub file: Utf8PathBuf,
    pub line_start: usize,
    pub line_end: usize,
    pub node_kind: SymbolKind,
    /// The bytes of the analyzed source this block covers, so `source[span] == code`. Offsets count bytes of the text the
    /// analyzer received, which is the file's lossy UTF-8 decoding and differs from the file's own bytes after any
    /// invalid sequence.
    pub span: Range<usize>,
    /// The position of the enclosing block in the file's block list, which is
    /// [`FileAnalysis::blocks`](crate::analysis::FileAnalysis::blocks) followed by
    /// [`FileAnalysis::test_blocks`](crate::analysis::FileAnalysis::test_blocks). `Some` exactly when `parent` is, the
    /// enclosing block's span contains this one's, and its position is lower, so the blocks of a file form a forest.
    pub parent_index: Option<usize>,
    /// The identifier the block declares, as the analyzer read it from the syntax tree: `mergeConfig` for
    /// `function mergeConfig(a, b)`, `Display for Foo` for `impl Display for Foo`. `None` for a block that declares no
    /// name, such as a re-export, an anonymous default export or a destructuring declaration.
    pub name: Option<String>,
    pub code: String,
    pub symbol_signature: Option<String>,
    pub matched_lines: Vec<usize>,
    /// The block this one is a member of, such as the class of a method; `None` for a top-level block.
    pub parent: Option<ParentContext>,
}

/// The symbol enclosing a [`CodeBlock`], such as the class or object literal a method block belongs to.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ParentContext {
    pub kind: SymbolKind,
    pub name: String,
}

/// A [`CodeBlock`] with its ranking scores.
#[derive(Debug, Clone)]
pub struct RankedBlock {
    pub block: CodeBlock,
    pub final_score: f64,
    pub rank: usize,
}

/// The kind of a [`Diagnostic`].
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[non_exhaustive]
pub enum DiagnosticKind {
    Degraded,
    Skipped,
    Warning,
    /// The file held bytes that are not UTF-8, so it was searched and extracted with each invalid sequence replaced by
    /// U+FFFD.
    LossyRead,
}

impl DiagnosticKind {
    /// What happened to a file this kind of diagnostic names, as a verb phrase for output.
    #[must_use]
    pub fn verb(self) -> &'static str {
        match self {
            Self::Degraded => "degraded",
            Self::Skipped => "skipped",
            Self::Warning => "warned",
            Self::LossyRead => "read lossily",
        }
    }
}

/// A non-fatal problem reported alongside a command's results.
#[derive(Debug, Clone)]
pub struct Diagnostic {
    pub kind: DiagnosticKind,
    pub path: Option<Utf8PathBuf>,
    pub message: String,
}

/// A single line matched by the text searcher.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct LineHit {
    pub line_number: usize,
    pub text: String,
    /// The byte offsets in `text` at which a match starts, in ascending order, as ranges of consecutive offsets: a match
    /// at offset 4 is `4..5` and one at each of 4, 5 and 6 is `4..7`. Where a match ends is not recorded. A line cut to
    /// the searcher's length limit records only the matches that start before the cut, so a hit whose matches all lie
    /// past it has none.
    pub match_starts: Vec<Range<usize>>,
}

/// The search command's response.
#[derive(Debug, Clone)]
pub struct SearchResponse {
    pub results: Vec<RankedBlock>,
    pub total_blocks_before_truncation: usize,
    pub truncated: bool,
    pub diagnostics: Vec<Diagnostic>,
}
use super::bm25::{as_f64, round6};
use crate::tokens::tokenize_source;
use crate::types::{CodeBlock, SymbolKind};

/// Returns the multiplier for how many query terms the block's declared name contains, from 1.0 to 3.0.
///
/// The name is [`CodeBlock::name`], the identifier the analyzer read from the syntax tree, so parameters, return types
/// and the body do not count. It is tokenized like a document, and the multiplier is
/// `round6(1 + 2 * matched / query_terms.len())`, where `matched` counts the query terms, repeats included, that the
/// name contains. Returns 1.0 when `query_terms` is empty or the block declares no name.
///
/// A body can mention every query word without the block being about them; a name that holds them says what it is.
///
/// # Examples
///
/// ```
/// use camino::Utf8PathBuf;
/// use monokl::rank::name_match_boost;
/// use monokl::types::{CodeBlock, SymbolKind};
///
/// let block = CodeBlock {
///     file: Utf8PathBuf::from("src/a.ts"),
///     line_start: 1,
///     line_end: 3,
///     node_kind: SymbolKind::Function,
///     span: 0..0,
///     parent_index: None,
///     name: Some("mergeConfig".to_string()),
///     code: String::new(),
///     symbol_signature: Some("function mergeConfig(a: Config, b: Config)".to_string()),
///     matched_lines: Vec::new(),
///     parent: None,
/// };
/// assert_eq!(name_match_boost(&block, &["merge", "config", "deep", "copy"]), 2.0);
/// ```
pub fn name_match_boost(block: &CodeBlock, query_terms: &[&str]) -> f64 {
    if query_terms.is_empty() {
        return 1.0;
    }
    let name_tokens = block.name.as_deref().map(tokenize_source).unwrap_or_default();
    let matched = query_terms.iter().filter(|term| name_tokens.iter().any(|token| token == *term)).count();
    round6(1.0 + 2.0 * as_f64(matched) / as_f64(query_terms.len()))
}

/// Returns the score multiplier for a block's symbol kind.
///
/// Callable units rank highest, then type definitions, then bindings; `Other` ranks lowest.
///
/// # Examples
///
/// ```
/// use monokl::rank::node_type_boost;
/// use monokl::types::SymbolKind;
///
/// assert_eq!(node_type_boost(SymbolKind::Function), 1.5);
/// assert_eq!(node_type_boost(SymbolKind::Other), 0.7);
/// ```
pub fn node_type_boost(kind: SymbolKind) -> f64 {
    match kind {
        SymbolKind::Function => 1.5,
        SymbolKind::Class | SymbolKind::Method | SymbolKind::Constructor => 1.4,
        SymbolKind::Interface | SymbolKind::Struct => 1.3,
        SymbolKind::TypeAlias | SymbolKind::Enum => 1.2,
        SymbolKind::Variable | SymbolKind::Impl => 1.1,
        SymbolKind::Property | SymbolKind::Field | SymbolKind::Macro => 1.0,
        SymbolKind::Module => 0.9,
        SymbolKind::Other => 0.7,
    }
}

#[cfg(test)]
// `allow`, not `expect`: clippy 1.99 stopped flagging float `assert_eq!`, so an expectation is unfulfilled there.
