enum Invariant {
    SpanInBounds,
    SpanOnCharBoundaries,
    SpanSlicesToCode,
    StartsAtDeclaration,
    NameInSpan,
    ParentIndexMatchesParent,
    ParentIndexInRange,
    ParentPrecedesChild,
    ParentEnclosesChild,
    ParentChainEnds,
    NoPartialOverlap,
    ParentIsInnermost,
}

