                && overlaps_significantly(&earlier.block, &candidate.block)
        });
        if !duplicate {
            kept.push(candidate);
        }
    }
    kept.iter()
        .enumerate()
        .map(|(idx, r)| (r.block.file.clone(), r.block.line_start, r.block.line_end, idx + 1))
        .collect()
}

