use camino::Utf8PathBuf;
use proptest::prelude::*;

use super::*;
use crate::types::{ParentContext, SymbolKind};

fn ranked(file: &str, span: Range<usize>, parent: Option<ParentContext>) -> RankedBlock {
    RankedBlock {
        block: CodeBlock {
            file: Utf8PathBuf::from(file),
            line_start: 1,
            line_end: 1,
            node_kind: SymbolKind::Method,
            span,
            parent_index: None,
            code: String::new(),
            symbol_signature: None,
            signature_span: None,
            name: None,
            matched_lines: Vec::new(),
            parent,
        },
        final_score: 0.0,
        rank: 0,
    }
}

/// Whether `later` repeats `earlier` under the rule the docs state: neither is a member the other encloses, and they
/// share more than half of the smaller span.
fn repeats(earlier: &CodeBlock, later: &CodeBlock) -> bool {
    !encloses_member(earlier, later) && !encloses_member(later, earlier) && overlaps_significantly(earlier, later)
}

/// Blocks that may be members, many per file, with nested and partly overlapping spans of widely varying length, some
/// empty and some inverted.
fn dense_block_strategy() -> impl Strategy<Value = RankedBlock> {
    let parent = ParentContext { kind: SymbolKind::Class, name: "Foo".to_owned() };
    (
        prop::sample::select(vec!["a.ts", "b.rs", "c/d.ts"]),
        0usize..120,
        prop_oneof![8 => 0usize..24, 3 => 24usize..120, 1 => Just(0usize)],
        prop::option::weighted(0.4, Just(parent)),
        0usize..100,
        prop::bool::weighted(0.05),
    )
        .prop_map(|(file, start, len, parent, rank, inverted)| {
            let span = if inverted { start + len..start } else { start..start + len };
            RankedBlock { rank, ..ranked(file, span, parent) }
        })
}

proptest! {
    // These three together say what dedup keeps: the survivors are a subsequence of the input, no survivor repeats an
    // earlier one, and every other block repeats a survivor before it.
    #[test]
    fn survivors_are_in_input_order_with_consecutive_ranks(blocks in prop::collection::vec(dense_block_strategy(), 0..120)) {
        let input: Vec<_> = blocks.iter().map(|r| (r.block.file.clone(), r.block.span.clone())).collect();
        let out = dedup_blocks(blocks);
        prop_assert_eq!(out.iter().map(|r| r.rank).collect::<Vec<_>>(), (1..=out.len()).collect::<Vec<_>>());
        let mut remaining = input.iter();
        for survivor in &out {
            let found = remaining.any(|(file, span)| *file == survivor.block.file && *span == survivor.block.span);
            prop_assert!(found, "{:?} is not in the input in order", survivor.block.span);
        }
    }

    #[test]
    fn no_survivor_repeats_an_earlier_survivor_in_its_file(blocks in prop::collection::vec(dense_block_strategy(), 0..120)) {
        let out = dedup_blocks(blocks);
        for (later_at, later) in out.iter().enumerate() {
            for earlier in &out[..later_at] {
                prop_assert!(
                    earlier.block.file != later.block.file || !repeats(&earlier.block, &later.block),
                    "{:?} repeats {:?}",
                    later.block.span,
                    earlier.block.span
                );
            }
        }
    }

    #[test]
    fn every_dropped_block_repeats_a_survivor_before_it(blocks in prop::collection::vec(dense_block_strategy(), 0..120)) {
        let out = dedup_blocks(blocks.clone());
        // A block's survivor position is found by walking both lists in order: a block is a survivor when it is the next
        // survivor in the walk.
        let mut survivors = out.iter().peekable();
        let mut before: Vec<&CodeBlock> = Vec::new();
        for block in &blocks {
            let is_survivor = survivors
                .next_if(|s| s.block.file == block.block.file && s.block.span == block.block.span)
                .is_some();
            if is_survivor {
                before.push(&block.block);
                continue;
            }
            let repeated = before.iter().any(|earlier| earlier.file == block.block.file && repeats(earlier, &block.block));
            prop_assert!(repeated, "{:?} was dropped without repeating a survivor", block.block.span);
        }
        prop_assert!(survivors.next().is_none());
    }
}

/// Spans that share no byte with each other, in a shuffled order, each claiming the same line.
fn disjoint_spans() -> impl Strategy<Value = Vec<Range<usize>>> {
    prop::collection::vec((0usize..4, 1usize..12), 0..40)
        .prop_map(|layout| {
            let mut at = 0;
            layout
                .into_iter()
                .map(|(gap, len)| {
                    at += gap;
                    let span = at..at + len;
                    at += len;
                    span
                })
                .collect::<Vec<_>>()
        })
        .prop_shuffle()
}

proptest! {
    #[test]
    fn blocks_that_share_no_byte_all_survive_whatever_lines_they_claim(spans in disjoint_spans(), lines in 0usize..4) {
        let blocks: Vec<_> = spans
            .iter()
            .map(|span| {
                let mut block = ranked("a.ts", span.clone(), None);
                block.block.line_start = lines;
                block.block.line_end = lines;
                block
            })
            .collect();
        let out = dedup_blocks(blocks);
        prop_assert_eq!(out.iter().map(|r| r.block.span.clone()).collect::<Vec<_>>(), spans);
    }
}

/// A class span over `0..` and members of at least three bytes that never overlap each other, in any order.
fn class_with_members() -> impl Strategy<Value = Vec<RankedBlock>> {
    prop::collection::vec((0usize..3, 3usize..8), 0..6)
        .prop_map(|layout| {
            let parent = ParentContext { kind: SymbolKind::Class, name: "Foo".to_owned() };
            let mut members = Vec::new();
            let mut at = 2;
            for (gap, len) in layout {
                at += gap;
                members.push(ranked("a.ts", at..at + len, Some(parent.clone())));
                at += len;
            }
            let mut blocks = vec![ranked("a.ts", 1..at + 1, None)];
            blocks.extend(members);
            blocks
        })
        .prop_shuffle()
}

proptest! {
    #[test]
    fn a_class_and_all_of_its_members_survive_in_any_rank_order(blocks in class_with_members()) {
        let mut expected: Vec<_> = blocks.iter().map(|r| (r.block.span.start, r.block.span.end)).collect();
        expected.sort_unstable();
        let mut actual: Vec<_> = dedup_blocks(blocks).iter().map(|r| (r.block.span.start, r.block.span.end)).collect();
        actual.sort_unstable();
        prop_assert_eq!(actual, expected);
    }
}

//! Work grows near-linearly with the number of matching files and candidate blocks.
//!
//! Each test runs one stage on an input and on one four times larger, takes the fastest of several runs of each so a
//! busy machine does not fail it, and asserts the time ratio. A step that is quadratic in its input would take 16 times
//! as long; the bound of 10 leaves room for cache effects and allocator noise. Only the ratio is asserted, never an
//! absolute time, so a slow runner does not fail it either.
#![allow(clippy::unwrap_used, clippy::expect_used, reason = "a failing assertion should panic in a test")]

use std::collections::HashMap;
use std::time::{Duration, Instant};

use camino::{Utf8Path, Utf8PathBuf};
use monokl::dedup::dedup_blocks;
use monokl::rank::{rank_blocks, tokenize_block};
use monokl::text_search::{TextSearchOptions, search_files};
use monokl::types::{CodeBlock, SymbolKind};

const SMALL: usize = 2_500;
const LARGE: usize = 4 * SMALL;
const RUNS: usize = 5;
/// A stage that scales linearly takes 4 times as long on the large input; a quadratic one takes 16 times.
const MAX_RATIO: f64 = 10.0;
/// Timings under this are noise, so the small input is never taken to be faster than it.
const TIMER_FLOOR: Duration = Duration::from_millis(1);

/// The fastest of `RUNS` runs of `work`, each on a fresh input from `setup` that is not part of the time.
fn fastest<T>(mut setup: impl FnMut() -> T, mut work: impl FnMut(T)) -> Duration {
    (0..RUNS)
        .map(|_| {
            let input = setup();
            let started = Instant::now();
            work(input);
            started.elapsed()
        })
        .min()
        .unwrap()
}

fn assert_near_linear(stage: &str, small: Duration, large: Duration) {
    let ratio = large.as_secs_f64() / small.max(TIMER_FLOOR).as_secs_f64();
    assert!(
        ratio < MAX_RATIO,
        "{stage}: {LARGE} inputs took {large:?} against {small:?} for {SMALL}, a ratio of {ratio:.1} (bound {MAX_RATIO})"
    );
}

/// How candidate blocks are laid out over files.
#[derive(Clone, Copy)]
enum Layout {
    /// Five blocks per file, none overlapping.
    ManyFiles,
    /// Every block in one file, none overlapping.
    OneFile,
    /// Every block in one file, each overlapping the ones around it.
    OneFileOverlapping,
}

fn candidates(count: usize, layout: Layout) -> Vec<(CodeBlock, Vec<String>)> {
    (0..count)
        .map(|index| {
            let (file, line_start, line_end) = match layout {
                Layout::ManyFiles => (format!("src/f{}.ts", index / 5), 1 + (index % 5) * 10, 8 + (index % 5) * 10),
                Layout::OneFile => ("src/one.ts".to_owned(), 1 + index * 4, 3 + index * 4),
                Layout::OneFileOverlapping => ("src/one.ts".to_owned(), 1 + index, 20 + index),
            };
            let code = format!("function handle{index}(input) {{\n  return needle + {index};\n}}");
            let block = CodeBlock {
                file: Utf8PathBuf::from(file),
                line_start,
                line_end,
                node_kind: SymbolKind::Function,
                span: 0..code.len(),
                parent_index: None,
                code,
                symbol_signature: Some(format!("function handle{index}(input)")),
                signature_span: None,
                name: None,
                matched_lines: vec![line_start + 1],
                parent: None,
            };
            let tokens = tokenize_block(&block);
            (block, tokens)
        })
        .collect()
}

fn rank_and_dedup(blocks: Vec<(CodeBlock, Vec<String>)>) {
    let df = HashMap::from([("needle".to_owned(), blocks.len())]);
    let ranked = dedup_blocks(rank_blocks(blocks, &["needle"], &df));
    assert!(!ranked.is_empty());
}

fn rank_and_dedup_scales_near_linearly(layout: Layout) {
    let small = fastest(|| candidates(SMALL, layout), rank_and_dedup);
    let large = fastest(|| candidates(LARGE, layout), rank_and_dedup);
    assert_near_linear("rank and dedup", small, large);
}

#[test]
fn ranking_and_dedup_scale_near_linearly_with_blocks_spread_over_files() {
    rank_and_dedup_scales_near_linearly(Layout::ManyFiles);
}

#[test]
fn ranking_and_dedup_scale_near_linearly_with_every_block_in_one_file() {
    rank_and_dedup_scales_near_linearly(Layout::OneFile);
}

#[test]
fn ranking_and_dedup_scale_near_linearly_with_overlapping_blocks_in_one_file() {
    rank_and_dedup_scales_near_linearly(Layout::OneFileOverlapping);
}

/// A temp directory with `count` small files that each match `needle`.
fn matching_files(count: usize) -> tempfile::TempDir {
    let dir = tempfile::tempdir().unwrap();
    for index in 0..count {
        let folder = dir.path().join(format!("d{:03}", index % 200));
        std::fs::create_dir_all(&folder).unwrap();
        let text = format!("export function needle{index}(a: number) {{\n  return a + {index};\n}}\n");
        std::fs::write(folder.join(format!("f{index:05}.ts")), text).unwrap();
    }
    dir
}

fn utf8(dir: &tempfile::TempDir) -> &Utf8Path {
    Utf8Path::from_path(dir.path()).expect("temp dir is UTF-8")
}

#[test]
fn text_search_scales_near_linearly_with_matching_files() {
    let (small_dir, large_dir) = (matching_files(SMALL), matching_files(LARGE));
    let search = |dir: &tempfile::TempDir| {
        let result = search_files(utf8(dir), &["needle"], &TextSearchOptions::default()).unwrap();
        assert!(result.files_total > 0);
    };
    let small = fastest(|| (), |()| search(&small_dir));
    let large = fastest(|| (), |()| search(&large_dir));
    assert_near_linear("text search", small, large);
}

#[cfg(feature = "lang-ts")]
#[test]
fn a_whole_search_scales_near_linearly_with_matching_files() {
    use std::sync::Arc;

    use monokl::analysis::registry::AnalyzerRegistry;
    use monokl::analysis::ts::TsAnalyzer;
    use monokl::pipeline::{SearchRequest, search};

    let (small_dir, large_dir) = (matching_files(SMALL), matching_files(LARGE));
    let registry = AnalyzerRegistry::new(vec![Arc::new(TsAnalyzer::new())]);
    let run = |dir: &tempfile::TempDir| {
        let request = SearchRequest {
            root: utf8(dir),
            query: "needle",
            exact: false,
            allow_tests: false,
            respect_ignore_files: true,
            language: None,
        };
        assert!(!search(&registry, &request).unwrap().ranked.is_empty());
    };
    let small = fastest(|| (), |()| run(&small_dir));
    let large = fastest(|| (), |()| run(&large_dir));
    assert_near_linear("whole search", small, large);
}

