"""Classifies how two binaries' outputs differ, per query: row set, snippet only, score only."""
import re
import subprocess
import sys
from pathlib import Path

ROOT = Path("/Users/gabe/Projects/monokl/.claude/worktrees/agent-aea747ffca5852cb9")
sys.argv = [sys.argv[0], sys.argv[1], sys.argv[2]]
OLD, NEW = Path(sys.argv[1]), Path(sys.argv[2])
CACHE = ROOT / "target/rg-compare"
exec(open(ROOT / "target/compare_outputs.py").read().split("def run(")[0].split("rows = []")[1].join(["rows = []", ""]) if False else "")

rows = []
for line in (ROOT / "scripts/rg-compare.questions").read_text().splitlines():
    if not line.strip() or line.startswith("#"):
        continue
    parts = [p.strip() for p in line.split("|")]
    rows.append((parts[0], parts[1], parts[3] if len(parts) > 3 else ""))
extra = ["string", "error", "export", "return", "this", "regex:\\w+ Error", "async function", "regex:^\\s*}", "regex:{}",
         "regex:\\)\\s*{", "regex:;\\s*\\w"]
repos = sorted(p.name for p in CACHE.iterdir() if p.is_dir())
queries = []
for repo, question, symbol in rows:
    if repo in repos:
        queries.append((repo, question))
        if symbol and symbol != "-":
            queries.append((repo, symbol))
queries += [(repo, q) for repo in repos for q in extra]
queries = list(dict.fromkeys(queries))


def run(binary, repo, query):
    return subprocess.run([str(binary), "search", query, "."], cwd=CACHE / repo, capture_output=True, text=True).stdout


def parse(text):
    out = []
    for line in text.splitlines()[1:]:
        if line.startswith("  ") and not line.startswith("  help"):
            out.append(line)
    return out


def key(row):
    # file,lineStart,lineEnd,kind -- the first four cells are never quoted
    return tuple(row.strip().split(",", 4)[:4])


summary = {"same": 0, "snippet_only": 0, "rows_added": 0, "rows_removed": 0, "rows_both": 0, "other": 0}
detail = {}
for repo, query in queries:
    old, new = run(OLD, repo, query), run(NEW, repo, query)
    if old == new:
        summary["same"] += 1
        continue
    o, n = parse(old), parse(new)
    ok, nk = [key(r) for r in o], [key(r) for r in n]
    if ok == nk:
        # same rows in same order: snippet or score only
        snippet_diff = any(a != b for a, b in zip(o, n))
        summary["snippet_only"] += 1
        detail.setdefault("snippet_only", []).append((repo, query))
    else:
        added = [k for k in nk if k not in ok]
        removed = [k for k in ok if k not in nk]
        if added and not removed:
            summary["rows_added"] += 1
            detail.setdefault("rows_added", []).append((repo, query, added[:4]))
        elif removed and not added:
            summary["rows_removed"] += 1
            detail.setdefault("rows_removed", []).append((repo, query, removed[:4]))
        elif added and removed:
            summary["rows_both"] += 1
            detail.setdefault("rows_both", []).append((repo, query, added[:3], removed[:3]))
        else:
            summary["other"] += 1
            detail.setdefault("other", []).append((repo, query))
print(summary)
for kind, items in detail.items():
    print("==", kind, len(items))
    for item in items:
        print("  ", item)

