        if a[6] != b[6]:
            ol, nl = snippet_lines(a[6]), snippet_lines(b[6])
            ol_core = [l for l in ol if re.match(r"\d+: ", l)]
            nl_core = [l for l in nl if re.match(r"\d+: ", l)]
            num = lambda l: int(l.split(":", 1)[0])
            onum, nnum = [num(l) for l in ol_core], [num(l) for l in nl_core]
            gone = [l for l in ol_core if num(l) not in nnum]
            came = [l for l in nl_core if num(l) not in onum]
            if came and not all(num(l) > max(onum) for l in came):
                print("SUSPECT", repo, query, a[0], a[1], onum, nnum)
