            if came and len(ol_core) >= 3 and gone:
                kind = "promoted"
            elif came:
                kind = "ADDED"
            else:
                kind = "removed"
            examples.append((kind, repo, query, a[0], a[1], a[2], a[5][:110], gone, came))
print(col_diffs)
print(Counter(e[0] for e in examples))
shown = Counter()
for e in examples:
    if shown[e[0]] < SHOW:
        shown[e[0]] += 1
        print(e)

